// Valida y normaliza el JSON que llega por el webhook.
// Acepta nombres en español (titulo, descripcion, origen, fecha)
// y sus equivalentes en inglés (title, description, source, timestamp).

const MAX_TITULO = 200;
const MAX_DESCRIPCION = 2000;
const MAX_ORIGEN = 100;

const cuerpo = $input.item.json.body;
const entrada = cuerpo && typeof cuerpo === 'object' ? cuerpo : {};

function leerTexto(valor) {
  return typeof valor === 'string' ? valor.trim() : '';
}

const titulo = leerTexto(entrada.titulo ?? entrada.title);
const descripcion = leerTexto(entrada.descripcion ?? entrada.description);
const origen = leerTexto(entrada.origen ?? entrada.source) || 'desconocido';
const fechaRecibida = entrada.fecha ?? entrada.timestamp;

const errores = [];
if (!titulo) errores.push('titulo es obligatorio');
if (!descripcion) errores.push('descripcion es obligatoria');
if (titulo.length > MAX_TITULO) errores.push(`titulo supera ${MAX_TITULO} caracteres`);
if (descripcion.length > MAX_DESCRIPCION) errores.push(`descripcion supera ${MAX_DESCRIPCION} caracteres`);
if (origen.length > MAX_ORIGEN) errores.push(`origen supera ${MAX_ORIGEN} caracteres`);

// Si no viene fecha, se usa el momento de recepción.
let fecha = new Date();
if (fechaRecibida !== undefined && fechaRecibida !== null && fechaRecibida !== '') {
  fecha = new Date(fechaRecibida);
  if (Number.isNaN(fecha.getTime())) {
    errores.push('fecha no es válida (usa formato ISO 8601, ej. 2026-11-12T10:30:00Z)');
  }
}

if (errores.length > 0) {
  return { json: { valida: false, errores } };
}

return {
  json: { valida: true, titulo, descripcion, origen, fecha: fecha.toISOString() },
};

// Decide la severidad final de la alerta.
// Modo 1: usa la respuesta del modelo local (llama.cpp).
// Modo 2 (respaldo): si el modelo no respondió o respondió algo inválido,
// clasifica por palabras clave. Así el flujo siempre funciona.

const alerta = $('Validar y normalizar').first().json;
const respuestaModelo = $input.item.json;

const SEVERIDADES = ['baja', 'media', 'alta', 'critica'];

// Las reglas se evalúan de la más grave a la menos grave; gana la primera que coincida.
// Las palabras van sin tildes y en minúsculas.
const REGLAS = [
  {
    severidad: 'critica',
    palabras: ['ransomware', 'exfiltracion', 'exfiltration', 'fuga de datos', 'data breach',
      'remote code execution', 'ejecucion remota', 'domain admin', 'cifrado masivo'],
  },
  {
    severidad: 'alta',
    palabras: ['malware', 'fuerza bruta', 'brute force', 'escalada de privilegios',
      'privilege escalation', 'phishing', 'inyeccion sql', 'sql injection',
      'command and control', 'credenciales', 'credential'],
  },
  {
    severidad: 'media',
    palabras: ['escaneo de puertos', 'port scan', 'login fallido', 'failed login',
      'sospechos', 'suspicious', 'anomal', 'vulnerab', 'policy violation'],
  },
];

function normalizarTexto(texto) {
  return texto.normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
}

// Devuelve 'baja' | 'media' | 'alta' | 'critica', o null si la respuesta no sirve.
function leerSeveridadDelModelo(respuesta) {
  const contenido = respuesta?.choices?.[0]?.message?.content;
  if (typeof contenido !== 'string') return null;
  const palabra = normalizarTexto(contenido).replace(/[^a-z]/g, '');
  return SEVERIDADES.includes(palabra) ? palabra : null;
}

function clasificarPorReglas(texto) {
  const textoNormalizado = normalizarTexto(texto);
  for (const regla of REGLAS) {
    if (regla.palabras.some((palabra) => textoNormalizado.includes(palabra))) {
      return regla.severidad;
    }
  }
  return 'baja';
}

const severidadModelo = leerSeveridadDelModelo(respuestaModelo);
const severidad = severidadModelo ?? clasificarPorReglas(`${alerta.titulo} ${alerta.descripcion}`);

return {
  json: {
    ...alerta,
    severidad,
    clasificado_por: severidadModelo ? 'llm' : 'reglas',
  },
};

